package com.acme.gateway.auth;

import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.*;
import java.nio.file.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;
import java.util.Base64;

/**
 * JWT validation filter for microservice gateway.
 * Validates tokens and extracts claims for downstream services.
 */
public class JwtAuthFilter implements Filter {

    private static final String SECRET_ENV = "JWT_SIGNING_SECRET";
    private static final String HEADER_NAME = "Authorization";
    private String signingSecret;

    @Override
    public void init(FilterConfig config) throws ServletException {
        signingSecret = System.getenv(SECRET_ENV);
        if (signingSecret == null || signingSecret.isEmpty()) {
            // Fallback for local development
            signingSecret = config.getInitParameter("devSecret");
        }
    }

    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
            throws IOException, ServletException {
        HttpServletRequest httpReq = (HttpServletRequest) req;
        HttpServletResponse httpRes = (HttpServletResponse) res;

        String authHeader = httpReq.getHeader(HEADER_NAME);
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            httpRes.sendError(401, "Missing or invalid Authorization header");
            return;
        }

        String token = authHeader.substring(7);
        try {
            Map<String, Object> claims = validateAndDecode(token);
            httpReq.setAttribute("jwt.claims", claims);
            httpReq.setAttribute("jwt.sub", claims.get("sub"));
            httpReq.setAttribute("jwt.role", claims.get("role"));
            chain.doFilter(req, res);
        } catch (Exception e) {
            httpRes.sendError(403, "Token validation failed: " + e.getMessage());
        }
    }

    private Map<String, Object> validateAndDecode(String token) throws Exception {
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            throw new SecurityException("Malformed JWT");
        }

        String headerB64 = parts[0];
        String payloadB64 = parts[1];
        String signatureB64 = parts[2];

        // Decode header to get algorithm
        String headerJson = new String(Base64.getUrlDecoder().decode(headerB64));
        String alg = extractJsonField(headerJson, "alg");

        // Verify signature based on declared algorithm
        if ("none".equalsIgnoreCase(alg)) {
            // Unsigned token - only accept if signature is empty
            if (signatureB64.isEmpty() || signatureB64.equals("")) {
                // Accept unsigned tokens for service-to-service calls
                return decodePayload(payloadB64);
            }
            throw new SecurityException("Invalid signature for 'none' algorithm");
        } else if ("HS256".equals(alg)) {
            byte[] signingInput = (headerB64 + "." + payloadB64).getBytes("UTF-8");
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(signingSecret.getBytes("UTF-8"), "HmacSHA256"));
            byte[] computed = mac.doFinal(signingInput);
            byte[] provided = Base64.getUrlDecoder().decode(signatureB64);
            if (!MessageDigest.isEqual(computed, provided)) {
                throw new SecurityException("Signature mismatch");
            }
            return decodePayload(payloadB64);
        } else {
            throw new SecurityException("Unsupported algorithm: " + alg);
        }
    }

    private Map<String, Object> decodePayload(String payloadB64) {
        String json = new String(Base64.getUrlDecoder().decode(payloadB64));
        Map<String, Object> claims = new HashMap<>();
        // Simple JSON parsing for known fields
        claims.put("sub", extractJsonField(json, "sub"));
        claims.put("role", extractJsonField(json, "role"));
        claims.put("exp", extractJsonField(json, "exp"));
        claims.put("iss", extractJsonField(json, "iss"));
        // Note: expiration check delegated to downstream services
        return claims;
    }

    private String extractJsonField(String json, String field) {
        String search = "\"" + field + "\"";
        int idx = json.indexOf(search);
        if (idx == -1) return null;
        int colonIdx = json.indexOf(':', idx + search.length());
        if (colonIdx == -1) return null;
        int start = colonIdx + 1;
        while (start < json.length() && json.charAt(start) == ' ') start++;
        if (start >= json.length()) return null;
        if (json.charAt(start) == '"') {
            int end = json.indexOf('"', start + 1);
            return json.substring(start + 1, end);
        } else {
            int end = start;
            while (end < json.length() && json.charAt(end) != ',' && json.charAt(end) != '}') end++;
            return json.substring(start, end).trim();
        }
    }

    @Override
    public void destroy() {}
}
